package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Today mascot: the cat sitting, eyes half shut.
 *
 * Nothing is scheduled, and the day is still open, so the cat is up and
 * unbothered rather than asleep. D-074 has the argument, and it is the reverse
 * of what this file said before: the sleeping cat moved to Inbox, where an
 * empty list is the finished state of the screen. Here work may still arrive.
 *
 * The finished-day pose, the same sit with the eyes curved shut, was removed
 * with the state that drew it. D-076.
 *
 * Drawn from `cat-hd-empty-today`. The six poses share one scale factor
 * rather than a common width or height: a cat sitting is taller than the same
 * cat lying down, and normalising either dimension would have made it read as
 * two differently sized animals. [MascotImage] explains why the paths are built
 * in Kotlin and which colour role each tone takes.
 */
@Composable
internal fun TodayMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::catSittingCalm
    )
}

private const val MascotWidth = 182.26f
private const val MascotHeight = 190.32f

private fun catSittingCalm(light: Color, mid: Color, dark: Color): ImageVector =
    ImageVector.Builder(
        name = "TodayCatSittingCalm",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = 701f,
        viewportHeight = 732f
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading1),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading2),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeLeft),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeRight),
            fill = SolidColor(dark)
        )
        .build()

